import{_ as e,a as r,c as o,b as a}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"01-Git-pr-fix","description":"","frontmatter":{"title":"01-Git-pr-fix"},"headers":[],"relativePath":"posts/开发经验/Git与版本控制/01-Git-pr-fix.md","filePath":"posts/开发经验/Git与版本控制/01-Git-pr-fix.md"}'),i={name:"posts/开发经验/Git与版本控制/01-Git-pr-fix.md"};function n(s,t,c,p,l,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="_2026-05-08" tabindex="-1">2026-05-08 <a class="header-anchor" href="#_2026-05-08" aria-label="Permalink to &quot;2026-05-08&quot;">​</a></h2><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/66e3b816-2293-457a-8e5e-41a37513d50d.png" alt="66e3b816-2293-457a-8e5e-41a37513d50d" referrerpolicy="no-referrer" loading="lazy"></p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>我提交了一个 pr 之后，代码中发现了错误的修改，需要被打回修复。当我修复了之后，再次提交代码的时候，不知道怎么提交。</p><h3 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h3><p>疑问：直接 commit 是在原来的分支上进行提交，对 pr 会有影响吗？怎么同步更新 pr 呢？</p><p>这里的 Amend 是什么意思？怎么理解？</p><h3 id="answer" tabindex="-1">Answer <a class="header-anchor" href="#answer" aria-label="Permalink to &quot;Answer&quot;">​</a></h3><p><strong>继续在同一个分支上修改</strong>，PR 会自动更新：GitHub、GitLab 等平台会检测到分支有新的提交（或强制推的改动），PR 页面会立刻同步你修复后的代码，维护者就能看到更新后的差异，并重新进行审查。</p><p><strong>总结</strong>：在原有分支上改完、推送，PR 自动更新，直接通知 reviewer 重新审查即可。</p><hr><p><code>git commit --amend</code> <strong>不会新增一个 commit 记录</strong>，而是<strong>修改最近的一次 commit</strong>（替换掉它）。 它会将你<strong>当前暂存区的内容</strong>与上一次 commit 的内容合并，并允许你<strong>重新编辑 commit 信息</strong>。</p><p><strong>具体效果</strong>：</p><ul><li>原 commit 被丢弃，生成一个<strong>新的 commit</strong>（但 commit ID 会变）。</li><li>历史中看起来还是只有那一个 commit，没有多余的“修复记录”。</li><li>如果已经推送到远程分支（比如 PR 对应的分支），需要 <code>git push --force</code>（或 <code>--force-with-lease</code>）才能覆盖远程分支。</li></ul>',14)])])}const g=e(i,[["render",n]]);export{h as __pageData,g as default};
